      "\u6761\u4EF6\u4ED8\u304D\u78BA\u7387\u306F\u300C\u3042\u308B\u6761\u4EF6\u306E\u3082\u3068\u3067\u306E\u78BA\u7387\u300D\u3067\u3059\u3002\u30D9\u30A4\u30BA\u306E\u5B9A\u7406\u306F\u3001\u7D50\u679C\u304B\u3089\u539F\u56E0\u5074\u306E\u78BA\u7387\u3092\u9006\u7B97\u3059\u308B\u5F0F\u3067\u3001\u691C\u67FB\u306E\u4F8B\u3067\u8A08\u7B97\u3057\u3066\u307F\u307E\u3059\u3002\u3042\u308B\u75BE\u60A3\u306E\u6709\u75C5\u7387\u304C1%\u3001\u691C\u67FB\u306E\u611F\u5EA6\uFF08\u75BE\u60A3\u304C\u3042\u308B\u4EBA\u3092\u967D\u6027\u3068\u3059\u308B\u5272\u5408\uFF09\u304C90%\u3001\u7279\u7570\u5EA6\uFF08\u75BE\u60A3\u304C\u306A\u3044\u4EBA\u3092\u9670\u6027\u3068\u3059\u308B\u5272\u5408\uFF09\u304C95%\u3060\u3068\u3057\u307E\u3059\u30021\u4E07\u4EBA\u3067\u306F\u75BE\u60A3\u306E\u3042\u308B\u4EBA\u304C100\u4EBA\u3067\u3001\u305D\u306E\u3046\u3061\u967D\u6027\u306F90\u4EBA\u3002\u75BE\u60A3\u306E\u306A\u30449,900\u4EBA\u306E\u3046\u30615%\u306E495\u4EBA\u304C\u8AA4\u3063\u3066\u967D\u6027\u306B\u306A\u308A\u307E\u3059\u3002\u3057\u305F\u304C\u3063\u3066\u967D\u6027\u8005\u306E\u3046\u3061\u672C\u5F53\u306B\u75BE\u60A3\u304C\u3042\u308B\u5272\u5408\u306F 90\xF7(90+495)\u225215.4% \u3067\u3059\u3002\u7CBE\u5EA6\u306E\u9AD8\u3044\u691C\u67FB\u3067\u3082\u3001\u6709\u75C5\u7387\u304C\u4F4E\u3044\u3068\u507D\u967D\u6027\u306E\u7D76\u5BFE\u6570\u304C\u591A\u304F\u306A\u308A\u3001\u967D\u6027\u306E\u610F\u5473\u306F\u5F31\u307E\u308A\u307E\u3059\u3002",
      "\u671F\u5F85\u5024\u306F\u78BA\u7387\u3067\u91CD\u307F\u4ED8\u3051\u3057\u305F\u5E73\u5747\u3001\u5206\u6563\u306F\u671F\u5F85\u5024\u304B\u3089\u306E\u3070\u3089\u3064\u304D\u306E\u4E8C\u4E57\u306E\u5E73\u5747\u3067\u3059\u3002\u30B5\u30A4\u30B3\u30ED1\u500B\u306E\u76EE\u306F\u671F\u5F85\u5024\u304C (1+2+3+4+5+6)\xF76=3.5\u3001\u4E8C\u4E57\u306E\u671F\u5F85\u5024\u304C (1+4+9+16+25+36)\xF76=91\xF76 \u306A\u306E\u3067\u3001\u5206\u6563\u306F 91\xF76\u22123.5\xB2=35\xF712\u22522.92\u3001\u6A19\u6E96\u504F\u5DEE\u306F\u7D041.71\u3067\u3059\u3002\u5206\u6563\u306E\u8A08\u7B97\u3067\u306F\u300C\u4E8C\u4E57\u306E\u671F\u5F85\u5024\u2212\u671F\u5F85\u5024\u306E\u4E8C\u4E57\u300D\u3068\u3044\u3046\u95A2\u4FC2\u3092\u4F7F\u3046\u3068\u52B9\u7387\u7684\u3067\u3059\u3002",
      "\u4EE3\u8868\u7684\u306A\u5206\u5E03\u3068\u3057\u3066\u3001\u6210\u529F\u78BA\u7387p\u306E\u8A66\u884C\u3092n\u56DE\u7E70\u308A\u8FD4\u3057\u305F\u6210\u529F\u56DE\u6570\u304C\u5F93\u3046\u4E8C\u9805\u5206\u5E03\u304C\u3042\u308A\u307E\u3059\u3002\u8868\u88CF\u304C\u7B49\u78BA\u7387\u306E\u30B3\u30A4\u30F3\u30925\u56DE\u6295\u3052\u3066\u8868\u304C\u3061\u3087\u3046\u30693\u56DE\u51FA\u308B\u78BA\u7387\u306F\u3001\u7D44\u307F\u5408\u308F\u305B\u306E\u6570 C(5,3)=10 \u3092\u5168\u4F53\u306E32\u901A\u308A\u3067\u5272\u308A\u300110\xF732=0.3125 \u3067\u3059\u3002\u6E2C\u5B9A\u5024\u306E\u5206\u5E03\u306E\u8FD1\u4F3C\u306B\u4F7F\u3046\u6B63\u898F\u5206\u5E03\u3067\u306F\u3001\u5E73\u5747\xB11\u6A19\u6E96\u504F\u5DEE\u306B\u7D0468%\u3001\xB12\u6A19\u6E96\u504F\u5DEE\u306B\u7D0495%\u304C\u5165\u308B\u3068\u3044\u3046\u76EE\u5B89\uFF08\u7D4C\u9A13\u5247\uFF09\u304C\u8A08\u7B97\u306E\u624B\u304C\u304B\u308A\u306B\u306A\u308A\u307E\u3059\u3002",
      "\u76F8\u95A2\u4FC2\u6570\u306F2\u5909\u6570\u306E\u76F4\u7DDA\u7684\u306A\u95A2\u4FC2\u306E\u5F37\u3055\u3092 \u22121 \u304B\u3089 1 \u3067\u8868\u3057\u3001\u56DE\u5E30\u76F4\u7DDA\u306F\u305D\u306E\u95A2\u4FC2\u3092\u5F0F\u306B\u3057\u305F\u3082\u306E \u3067\u3059\u3002\u56DE\u5E30\u4FC2\u6570\uFF08\u50BE\u304D\uFF09\u306F\u3001\u76F8\u95A2\u4FC2\u6570\u306B\u300C\u76EE\u7684\u5909\u6570\u306E\u6A19\u6E96\u504F\u5DEE\xF7\u8AAC\u660E\u5909\u6570\u306E\u6A19\u6E96\u504F\u5DEE\u300D\u3092\u639B\u3051\u305F\u3082\u306E\u306B\u306A\u308A\u307E\u3059\u3002\u76F8\u95A2\u304C\u3042\u3063\u3066\u3082\u56E0\u679C\u3068\u306F\u9650\u3089\u305A\u3001\u7B2C\u4E09\u306E\u5909\u6570\uFF08\u4EA4\u7D61\u56E0\u5B50\uFF09\u304C\u4E21\u65B9\u306B\u52B9\u3044\u3066\u3044\u308B\u5834\u5408\u304C\u3042\u308A\u307E\u3059\u3002\u8A08\u7B97\u3067\u304D\u308B\u3053\u3068\u3068\u89E3\u91C8\u3057\u3066\u3088\u3044\u3053\u3068\u306F\u5206\u3051\u3066\u8003\u3048\u308B\u5FC5\u8981\u304C\u3042\u308A\u307E\u3059\u3002",
      "\u60C5\u5831\u91CF\u306E\u8A08\u7B97\u3067\u306F\u3001\u78BA\u7387p\u3067\u8D77\u304D\u308B\u4E8B\u8C61\u306E\u81EA\u5DF1\u60C5\u5831\u91CF\u304C \u2212log2(p) \u30D3\u30C3\u30C8\u3067\u3059\u3002\u30A8\u30F3\u30C8\u30ED\u30D4\u30FC\u306F\u305D\u306E\u671F\u5F85\u5024\u3067\u3001\u78BA\u7387\u5206\u5E03 (0.5, 0.25, 0.25) \u306E\u5834\u5408\u30010.5\xD71+0.25\xD72+0.25\xD72=1.5\u30D3\u30C3\u30C8\u3068\u8A08\u7B97\u3067\u304D\u307E\u3059\u3002\u76F8\u4E92\u60C5\u5831\u91CF\u306F\u3001\u7247\u65B9\u3092\u77E5\u308B\u3053\u3068\u3067\u4ED6\u65B9\u306E\u4E0D\u78BA\u5B9F\u6027\u304C\u3069\u308C\u3060\u3051\u6E1B\u308B\u304B\u3092\u8868\u3057\u30012\u5909\u6570\u306E\u5206\u5E03\u3068\u5468\u8FBA\u5206\u5E03\u306E\u305A\u308C\uFF08KL\u30C0\u30A4\u30D0\u30FC\u30B8\u30A7\u30F3\u30B9\uFF09\u3068\u3057\u3066\u66F8\u3051\u307E\u3059\u3002\u52FE\u914D\u964D\u4E0B\u6CD5\u306E\u8A08\u7B97\u4F8B\u3068\u3057\u3066\u3001f(x)=x\xB2\u3001\u5B66\u7FD2\u73870.1\u3001\u958B\u59CB\u70B9x=4 \u306E\u5834\u5408\u3001\u52FE\u914D\u306F 2x=8 \u306A\u306E\u3067\u6B21\u306E\u70B9\u306F 4\u22120.1\xD78=3.2\u3001\u6B21\u306F 3.2\u22120.1\xD76.4=2.56 \u3068\u3001\u6700\u5C0F\u70B90\u3078\u8FD1\u3065\u3044\u3066\u3044\u304D\u307E\u3059\u3002"
