      "\u6D3B\u7528\u4E8B\u4F8B\u306B\u306F\u3001\u30B3\u30FC\u30C9\u751F\u6210\u3084\u30D7\u30EB\u30EA\u30AF\u30A8\u30B9\u30C8\u306E\u4F5C\u6210\u3092\u652F\u63F4\u3059\u308B\u30B3\u30FC\u30C7\u30A3\u30F3\u30B0\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u3001\u30D6\u30E9\u30A6\u30B6\u3084PC\u3092\u64CD\u4F5C\u3059\u308B\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u3001\u8907\u6570\u30BD\u30FC\u30B9\u3092\u6A2A\u65AD\u8ABF\u67FB\u3059\u308B\u30C7\u30A3\u30FC\u30D7\u30EA\u30B5\u30FC\u30C1\u3001\u5B9A\u578B\u696D\u52D9\u306E\u81EA\u52D5\u5316\u306A\u3069\u304C\u3042\u308A\u307E\u3059\u3002\u696D\u52D9\u3078\u306E\u5C0E\u5165\u3067\u306F\u3001\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u306B\u4EFB\u305B\u308B\u7BC4\u56F2\u3068\u4EBA\u9593\u304C\u62C5\u3046\u7BC4\u56F2\u306E\u5F79\u5272\u5206\u62C5\u3092\u5148\u306B\u6C7A\u3081\u308B\u3053\u3068\u304C\u91CD\u8981\u3067\u3059\u3002",
      "\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u7279\u6709\u306E\u30EA\u30B9\u30AF\u3068\u3057\u3066\u3001\u6A29\u9650\u306E\u904E\u5270\u4ED8\u4E0E\u304C\u3042\u308A\u307E\u3059\u3002\u5FC5\u8981\u4EE5\u4E0A\u306E\u30A2\u30AF\u30BB\u30B9\u6A29\u9650\u3092\u4E0E\u3048\u308B\u3068\u3001\u8AA4\u52D5\u4F5C\u3084\u653B\u6483\u306E\u969B\u306E\u88AB\u5BB3\u7BC4\u56F2\u304C\u5E83\u304C\u308A\u307E\u3059\u3002\u307E\u305F\u3001\u4E00\u3064\u306E\u5DE5\u7A0B\u306E\u8AA4\u308A\u304C\u5F8C\u7D9A\u306E\u5DE5\u7A0B\u306B\u4F1D\u64AD\u3059\u308B\u9023\u9396\u7684\u306A\u30A8\u30E9\u30FC\u306E\u62E1\u5927\u3082\u3001\u81EA\u5F8B\u7684\u306B\u8907\u6570\u5DE5\u7A0B\u3092\u9032\u3081\u308B\u4ED5\u7D44\u307F\u306A\u3089\u3067\u306F\u306E\u30EA\u30B9\u30AF\u3067\u3059\u3002",
      "\u30D7\u30ED\u30F3\u30D7\u30C8\u30A4\u30F3\u30B8\u30A7\u30AF\u30B7\u30E7\u30F3\u306F\u3001\u5916\u90E8\u6587\u66F8\u3084\u30C4\u30FC\u30EB\u304B\u3089\u306E\u51FA\u529B\u306E\u4E2D\u306B\u7D1B\u308C\u305F\u6307\u793A\u6587\u306B\u3088\u3063\u3066\u3001\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u304C\u672C\u6765\u306E\u6307\u793A\u3068\u306F\u7570\u306A\u308B\u52D5\u4F5C\u3092\u3059\u308B\u3088\u3046\u8A98\u5C0E\u3055\u308C\u308B\u653B\u6483\u3067\u3059\u3002\u5BFE\u7B56\u306F\u4E00\u3064\u306E\u65B9\u6CD5\u306B\u983C\u3089\u305A\u3001\u5165\u529B\u3068\u6307\u793A\u306E\u533A\u5225\u3001\u6A29\u9650\u306E\u5236\u9650\u3001\u51FA\u529B\u306E\u691C\u8A3C\u306A\u3069\u3092\u7D44\u307F\u5408\u308F\u305B\u308B\u591A\u5C64\u9632\u5FA1\u304C\u57FA\u672C\u306B\u306A\u308A\u307E\u3059\u3002",
      "\u5B89\u5168\u306B\u4F7F\u3046\u305F\u3081\u306E\u539F\u5247\u3068\u3057\u3066\u3001\u6700\u5C0F\u6A29\u9650\u306E\u539F\u5247\uFF08\u6A29\u9650\u306F\u30BF\u30B9\u30AF\u306B\u5FC5\u8981\u306A\u7BC4\u56F2\u3060\u3051\u306B\u7D5E\u308B\uFF09\u3001\u30B5\u30F3\u30C9\u30DC\u30C3\u30AF\u30B9\u3084\u30DB\u30EF\u30A4\u30C8\u30EA\u30B9\u30C8\u306B\u3088\u308B\u5B9F\u884C\u7BC4\u56F2\u306E\u5236\u9650\u3001\u91CD\u8981\u306A\u64CD\u4F5C\u3078\u306E\u4EBA\u9593\u306E\u627F\u8A8D\u3001\u69CB\u9020\u5316\u51FA\u529B\u306B\u3088\u308B\u5F62\u5F0F\u306E\u7D71\u5236\u3001\u30AC\u30FC\u30C9\u30EC\u30FC\u30EB\u306E\u8A2D\u5B9A\u304C\u6319\u3052\u3089\u308C\u307E\u3059\u3002",
      "\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u306E\u8A55\u4FA1\u3067\u306F\u3001Eval\uFF08\u8A55\u4FA1\u306E\u4ED5\u7D44\u307F\uFF09\u306B\u3088\u3063\u3066\u30BF\u30B9\u30AF\u304C\u6B63\u3057\u304F\u5B8C\u4E86\u3057\u305F\u304B\u3092\u6E2C\u308A\u3001\u904B\u7528\u4E2D\u3082\u7D99\u7D9A\u7684\u306A\u30E2\u30CB\u30BF\u30EA\u30F3\u30B0\u3067\u7570\u5E38\u3084\u54C1\u8CEA\u4F4E\u4E0B\u3092\u691C\u77E5\u3057\u307E\u3059\u3002\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u306F\u5C0E\u5165\u3057\u3066\u7D42\u308F\u308A\u3067\u306F\u306A\u304F\u3001\u8A55\u4FA1\u3068\u6539\u5584\u3092\u7D9A\u3051\u308B\u5BFE\u8C61\u3067\u3059\u3002\u5177\u4F53\u7684\u306A\u30C8\u30E9\u30D6\u30EB\u4E8B\u4F8B\u304B\u3089\u5B66\u3073\u3001\u6A29\u9650\u3084\u30AC\u30FC\u30C9\u30EC\u30FC\u30EB\u3092\u898B\u76F4\u3059\u3053\u3068\u3082\u904B\u7528\u306E\u4E00\u90E8\u3067\u3059\u3002"
