      "\u30D7\u30ED\u30F3\u30D7\u30C8\u30A8\u30F3\u30B8\u30CB\u30A2\u30EA\u30F3\u30B0\u306F\u3001\u30D7\u30ED\u30F3\u30D7\u30C8\uFF08\u6307\u793A\u6587\uFF09\u3092\u5DE5\u592B\u3057\u3066\u3001\u671B\u3080\u51FA\u529B\u3092\u5F97\u3084\u3059\u304F\u3059\u308B\u6280\u8853\u3067\u3059\u3002\u30D7\u30ED\u30F3\u30D7\u30C8\u306E\u57FA\u672C\u69CB\u6210\u8981\u7D20\u306F\u3001\u6307\u793A\u3001\u6587\u8108\u3084\u524D\u63D0\u3001\u5165\u529B\u30C7\u30FC\u30BF\u3001\u51FA\u529B\u5F62\u5F0F\u306E\u6307\u5B9A\u306A\u3069\u3067\u3059\u30021\u56DE\u3067\u5B8C\u6210\u3092\u76EE\u6307\u3059\u306E\u3067\u306F\u306A\u304F\u3001\u51FA\u529B\u3092\u898B\u3066\u6307\u793A\u3092\u76F4\u3059\u5BFE\u8A71\u7684\u306A\u6539\u5584\u3092\u7E70\u308A\u8FD4\u3059\u3053\u3068\u304C\u57FA\u672C\u59FF\u52E2\u306B\u306A\u308A\u307E\u3059\u3002",
      "\u4EE3\u8868\u7684\u306A\u624B\u6CD5\u3068\u3057\u3066\u3001\u4F8B\u3092\u793A\u3055\u305A\u6307\u793A\u3060\u3051\u3092\u4E0E\u3048\u308BZero-Shot\uFF08\u30BC\u30ED\u30B7\u30E7\u30C3\u30C8\uFF09\u30D7\u30ED\u30F3\u30D7\u30C6\u30A3\u30F3\u30B0\u3001\u5165\u529B\u3068\u671B\u307E\u3057\u3044\u51FA\u529B\u306E\u4F8B\u3092\u6570\u4EF6\u793A\u3059Few-Shot\u30D7\u30ED\u30F3\u30D7\u30C6\u30A3\u30F3\u30B0\u3001\u9014\u4E2D\u306E\u601D\u8003\u904E\u7A0B\u3092\u6BB5\u968E\u7684\u306B\u305F\u3069\u3089\u305B\u308BChain-of-Thought\uFF08\u601D\u8003\u306E\u9023\u9396\uFF09\u304C\u3042\u308A\u307E\u3059\u3002\u307E\u305F\u3001\u6587\u8108\u5185\u5B66\u7FD2\uFF08In-Context Learning\uFF09\u306F\u3001\u30E2\u30C7\u30EB\u306E\u91CD\u307F\u3092\u5909\u3048\u305A\u306B\u3001\u4E0E\u3048\u305F\u4F8B\u3084\u6587\u8108\u304B\u3089\u305D\u306E\u5834\u3067\u30BF\u30B9\u30AF\u306E\u30D1\u30BF\u30FC\u30F3\u3092\u8AAD\u307F\u53D6\u3089\u305B\u308B\u50CD\u304D\u3092\u6307\u3057\u307E\u3059\u3002\u5F79\u5272\u8A2D\u5B9A\u3084\u51FA\u529B\u5F62\u5F0F\u306E\u6307\u5B9A\u3001\u5BFE\u8C61\u8AAD\u8005\u3084\u5206\u91CF\u3068\u3044\u3063\u305F\u5177\u4F53\u5EA6\u306E\u30B3\u30F3\u30C8\u30ED\u30FC\u30EB\u3068\u7D44\u307F\u5408\u308F\u305B\u3066\u4F7F\u3044\u307E\u3059\u3002",
      "\u6587\u66F8\u4F5C\u6210\u30FB\u30B3\u30DF\u30E5\u30CB\u30B1\u30FC\u30B7\u30E7\u30F3\u696D\u52D9\u3067\u306F\u3001\u30D3\u30B8\u30CD\u30B9\u30E1\u30FC\u30EB\u3084\u5404\u7A2E\u30D3\u30B8\u30CD\u30B9\u6587\u66F8\u306E\u4F5C\u6210\u3001\u6821\u6B63\u30FB\u6DFB\u524A\u30FB\u6574\u5F62\u3001\u8981\u7D04\u3084\u8981\u70B9\u62BD\u51FA\u3001\u6587\u5B57\u8D77\u3053\u3057\u3068\u8B70\u4E8B\u9332\u306E\u4F5C\u6210\u3001\u7FFB\u8A33\u3001\u30D7\u30EC\u30BC\u30F3\u30C6\u30FC\u30B7\u30E7\u30F3\u30B9\u30E9\u30A4\u30C9\u306E\u4F5C\u6210\u306A\u3069\u306B\u6D3B\u7528\u3055\u308C\u307E\u3059\u3002\u751F\u6210AI\u306F\u4E0B\u66F8\u304D\u3084\u6574\u5F62\u3092\u901F\u304F\u3057\u307E\u3059\u304C\u3001\u4E8B\u5B9F\u78BA\u8A8D\u3068\u3001\u56FA\u6709\u540D\u8A5E\u3084\u6570\u5024\u306E\u30C1\u30A7\u30C3\u30AF\u306F\u4EBA\u9593\u304C\u884C\u3044\u307E\u3059\u3002",
      "\u4F01\u753B\u30FB\u30DE\u30FC\u30B1\u30C6\u30A3\u30F3\u30B0\u696D\u52D9\u3067\u306F\u3001\u30D6\u30EC\u30A4\u30F3\u30B9\u30C8\u30FC\u30DF\u30F3\u30B0\u3084\u58C1\u6253\u3061\u306E\u76F8\u624B\u3001\u30AD\u30E3\u30C3\u30C1\u30B3\u30D4\u30FC\u3084\u5E83\u544A\u30B3\u30D4\u30FC\u306E\u4F5C\u6210\u3001\u30A2\u30F3\u30B1\u30FC\u30C8\u306E\u8A2D\u8A08\u3068\u5206\u6790\u3001SNS\u6295\u7A3F\u3084\u30B3\u30F3\u30C6\u30F3\u30C4\u5236\u4F5C\u3001\u30E9\u30F3\u30C7\u30A3\u30F3\u30B0\u30DA\u30FC\u30B8\uFF08LP\uFF09\u306E\u4F5C\u6210\u3001\u5E02\u5834\u30FB\u7AF6\u5408\u30EA\u30B5\u30FC\u30C1\u306B\u6D3B\u7528\u3055\u308C\u307E\u3059\u3002\u30AF\u30EA\u30A8\u30A4\u30C6\u30A3\u30D6\u5236\u4F5C\u3067\u306F\u3001\u753B\u50CF\u30FB\u30D3\u30B8\u30E5\u30A2\u30EB\u7D20\u6750\u306E\u751F\u6210\u3001\u52D5\u753B\u30B3\u30F3\u30C6\u30F3\u30C4\u306E\u751F\u6210\u30FB\u7DE8\u96C6\u3001\u30CA\u30EC\u30FC\u30B7\u30E7\u30F3\u3084\u97F3\u58F0\u30FBBGM\u306E\u751F\u6210\u3001\u30ED\u30B4\u3084\u30C7\u30B6\u30A4\u30F3\u6848\u30FB\u30E2\u30C3\u30AF\u30A2\u30C3\u30D7\u306E\u4F5C\u6210\u3001\u65E2\u5B58\u7D20\u6750\u306E\u30D0\u30EA\u30A8\u30FC\u30B7\u30E7\u30F3\u5C55\u958B\u3084\u591A\u8A00\u8A9E\u30ED\u30FC\u30AB\u30E9\u30A4\u30BA\u304C\u5BFE\u8C61\u306B\u306A\u308A\u307E\u3059\u3002",
      "\u30C7\u30FC\u30BF\u5206\u6790\u30FB\u30EA\u30B5\u30FC\u30C1\u696D\u52D9\u3067\u306F\u3001\u30C7\u30FC\u30BF\u306E\u6574\u5F62\u30FB\u5206\u985E\u3001\u8868\u3084\u30C7\u30FC\u30BF\u306E\u96C6\u8A08\u3068\u53EF\u8996\u5316\u3001\u5927\u91CF\u6587\u66F8\u304B\u3089\u306E\u60C5\u5831\u62BD\u51FA\u30FB\u8981\u7D04\u3001\u8907\u6570\u30BD\u30FC\u30B9\u3092\u6A2A\u65AD\u3057\u3066\u8ABF\u67FB\u3059\u308B\u30C7\u30A3\u30FC\u30D7\u30EA\u30B5\u30FC\u30C1\u3001\u5B9A\u4F8B\u30EC\u30DD\u30FC\u30C8\u306E\u81EA\u52D5\u751F\u6210\u306A\u3069\u306B\u6D3B\u7528\u3055\u308C\u307E\u3059\u3002\u958B\u767A\u30FB\u696D\u52D9\u81EA\u52D5\u5316\u3067\u306F\u3001\u30B3\u30FC\u30C7\u30A3\u30F3\u30B0\u30A8\u30FC\u30B8\u30A7\u30F3\u30C8\u306B\u3088\u308B\u30B3\u30FC\u30C7\u30A3\u30F3\u30B0\u3084\u30A2\u30D7\u30EA\u958B\u767A\u306E\u652F\u63F4\u3001\u65E2\u5B58\u30B7\u30B9\u30C6\u30E0\u3084\u30B3\u30FC\u30C9\u30D9\u30FC\u30B9\u306E\u8ABF\u67FB\u3068\u30EA\u30D5\u30A1\u30AF\u30BF\u30EA\u30F3\u30B0\u3001\u30D6\u30E9\u30A6\u30B6\u64CD\u4F5C\u3092\u542B\u3080\u5B9A\u578B\u696D\u52D9\u306E\u81EA\u52D5\u5316\u3001\u8907\u6570\u30C4\u30FC\u30EB\u30FB\u8907\u6570\u30B9\u30C6\u30C3\u30D7\u3092\u6A2A\u65AD\u3059\u308B\u8907\u5408\u30BF\u30B9\u30AF\u306E\u81EA\u52D5\u5316\u304C\u9032\u3093\u3067\u3044\u307E\u3059\u3002"
