      "\u91CD\u307F\u306E\u66F4\u65B0\u306F\u300Cw \u2190 w \u2212 \u5B66\u7FD2\u7387 \xD7 \u52FE\u914D\u300D\u3068\u3044\u3046\u5F62\u3067\u8868\u3055\u308C\u307E\u3059\u3002\u52FE\u914D\u306F\u640D\u5931\u304C\u5897\u3048\u308B\u5411\u304D\u3092\u793A\u3059\u305F\u3081\u3001\u305D\u306E\u9006\u5411\u304D\u306B\u52D5\u304B\u3059\u3053\u3068\u3067\u640D\u5931\u304C\u6E1B\u308A\u307E\u3059\u3002\u5B66\u7FD2\u7387\u304C\u5927\u304D\u3059\u304E\u308B\u3068\u66F4\u65B0\u304C\u884C\u304D\u904E\u304E\u3066\u640D\u5931\u304C\u767A\u6563\u3057\u3001\u5C0F\u3055\u3059\u304E\u308B\u3068\u53CE\u675F\u307E\u3067\u6642\u9593\u304C\u304B\u304B\u308A\u307E\u3059\u3002\u300C\u52FE\u914D\u3092\u3069\u3046\u8A08\u7B97\u3059\u308B\u304B\u300D\u304C\u8AA4\u5DEE\u9006\u4F1D\u64AD\u6CD5\u3001\u300C\u52FE\u914D\u3092\u4F7F\u3063\u3066\u3069\u3046\u52D5\u304B\u3059\u304B\u300D\u304C\u52FE\u914D\u964D\u4E0B\u6CD5\u3067\u3001\u4E21\u8005\u306E\u5F79\u5272\u306F\u5225\u3067\u3042\u308B\u70B9\u304C\u6DF7\u540C\u3057\u3084\u3059\u3044\u30DD\u30A4\u30F3\u30C8\u3067\u3059\u3002",
      "CNN\uFF08\u7573\u307F\u8FBC\u307F\u30CB\u30E5\u30FC\u30E9\u30EB\u30CD\u30C3\u30C8\u30EF\u30FC\u30AF\uFF09\u306F\u3001\u753B\u50CF\u306E\u3088\u3046\u306A\u4E8C\u6B21\u5143\u30C7\u30FC\u30BF\u306E\u5C40\u6240\u7684\u306A\u30D1\u30BF\u30FC\u30F3\u3092\u6349\u3048\u308B\u69CB\u9020\u3067\u3059\u3002\u7573\u307F\u8FBC\u307F\u6F14\u7B97\u3067\u8FD1\u508D\u306E\u7279\u5FB4\u3092\u62BD\u51FA\u3057\u3001\u30D7\u30FC\u30EA\u30F3\u30B0\u3067\u60C5\u5831\u3092\u96C6\u7D04\u3059\u308B\u3053\u3068\u3067\u3001\u4F4D\u7F6E\u306E\u591A\u5C11\u306E\u305A\u308C\u306B\u5DE6\u53F3\u3055\u308C\u306B\u304F\u3044\u8868\u73FE\u3092\u5F97\u307E\u3059\u3002\u753B\u50CF\u8A8D\u8B58\u3092\u306F\u3058\u3081\u3068\u3059\u308B\u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30D3\u30B8\u30E7\u30F3\u306E\u767A\u5C55\u306E\u57FA\u76E4\u306B\u306A\u308A\u307E\u3057\u305F\u3002",
      "RNN\uFF08\u518D\u5E30\u578B\u30CB\u30E5\u30FC\u30E9\u30EB\u30CD\u30C3\u30C8\u30EF\u30FC\u30AF\uFF09\u306F\u3001\u904E\u53BB\u306E\u60C5\u5831\u3092\u96A0\u308C\u72B6\u614B\u3068\u3057\u3066\u4FDD\u6301\u3057\u306A\u304C\u3089\u7CFB\u5217\u3092\u9806\u306B\u51E6\u7406\u3057\u3001\u6587\u7AE0\u3084\u97F3\u58F0\u306E\u3088\u3046\u306A\u9806\u5E8F\u306E\u3042\u308B\u30C7\u30FC\u30BF\u3092\u6271\u3044\u307E\u3059\u3002\u305F\u3060\u3057\u5B66\u7FD2\u306E\u904E\u7A0B\u3067\u52FE\u914D\u304C\u6D88\u3048\u305F\u308A\u7206\u767A\u3057\u305F\u308A\u3059\u308B\u52FE\u914D\u6D88\u5931\u554F\u984C\u30FB\u52FE\u914D\u7206\u767A\u554F\u984C\u304C\u3042\u308A\u3001\u96E2\u308C\u305F\u60C5\u5831\u540C\u58EB\u306E\u95A2\u4FC2\u3092\u5B66\u3073\u306B\u304F\u3044\u5F31\u70B9\u304C\u3042\u308A\u307E\u3057\u305F\u3002\u5165\u529B\u30FB\u5FD8\u5374\u30FB\u51FA\u529B\u306E\u30B2\u30FC\u30C8\u3067\u4FDD\u6301\u3059\u308B\u60C5\u5831\u3092\u5236\u5FA1\u3059\u308BLSTM\u304C\u3001\u3053\u306E\u554F\u984C\u3092\u7DE9\u548C\u3059\u308B\u305F\u3081\u306B\u8003\u6848\u3055\u308C\u305F\u69CB\u9020\u3067\u3059\u3002",
