      "\u6700\u9069\u5316\u624B\u6CD5\uFF1ASGD\u3001\u30E2\u30FC\u30E1\u30F3\u30BF\u30E0\u3001AdaGrad\u3001RMSprop\u3001Adam\u3002Adam\u306F1\u6B21\u30FB2\u6B21\u30E2\u30FC\u30E1\u30F3\u30C8\u306E\u63A8\u5B9A\u3092\u7D44\u307F\u5408\u308F\u305B\u5B66\u7FD2\u7387\u3092\u9069\u5FDC\u3055\u305B\u307E\u3059\u3002",
      "\u8AA4\u5DEE\u95A2\u6570\u306F\u3001\u56DE\u5E30\u3067\u306F\u5E73\u5747\u4E8C\u4E57\u8AA4\u5DEE\u3001\u5206\u985E\u3067\u306F\u4EA4\u5DEE\u30A8\u30F3\u30C8\u30ED\u30D4\u30FC\u8AA4\u5DEE\u304C\u6A19\u6E96\u3067\u3059\u3002"
