    pitfalls: ["\u300C\u8907\u6570\u306E\u30B5\u30A4\u30C8\u306B\u66F8\u3044\u3066\u3042\u308B\u300D\u3060\u3051\u3067\u78BA\u5B9A\u3068\u3057\u306A\u3044"]
